def _has_external_dependencies(self, component: CodeComponent) -> bool:
        """Check if component has external dependencies"""
        external_patterns = [
            'import ',
            'from ',
            'require(',
            'include ',
        ]

        for pattern in external_patterns:
            if pattern in component.source_code:
                return True

        return False

